async function bootstrap(): Promise<void> {
  // F1：偏好（消息密度）必须在首屏生效，不能等设置页懒加载后才应用。
  initPreferences()
  // 生产构建已在构建期拦截 mock；这里再兜一层，防止 e2e 产物被误部署后连假数据。
