const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } })
const pp = await ctx.newPage()

async function protoShot(file, name, pageName, selector) {
  await pp.goto(`file://${ROOT}/docs/prototypes/${file}`)
  await pp.waitForTimeout(700)
  if (pageName) {
    await pp.evaluate(
      ([name, sel]) => {
        document.querySelectorAll(sel).forEach((el) => {
          el.hidden = el.getAttribute('data-page') !== name
        })
        document
          .querySelectorAll('.sb-nav-item[data-page], .rail-link[data-page]')
          .forEach((el) => el.classList.toggle('is-active', el.getAttribute('data-page') === name))
      },
      [pageName, selector],
    )
  }
  await pp.waitForTimeout(700)
  await pp.screenshot({ path: `${OUT}/${name}.png` })
  console.log('shot', name)
}

