function listParams(reset: boolean): KnowledgeListParams {
  const params: KnowledgeListParams = { limit: 20 }
  const q = keyword.value.trim()
  if (q) params.q = q
  if (categoryFilter.value !== 'all') params.category = categoryFilter.value
