const fs=require('fs');
const dev=JSON.parse(fs.readFileSync('.tmp/pixel/dev-styles.json','utf8'));
const proto=JSON.parse(fs.readFileSync('.tmp/pixel/proto-styles.json','utf8'));
const map=new Map(proto.map(p=>[p.sel.replace('#page-knowledge ',''),p]));
for(const d of dev){
  const key=d.sel.replace('#page-knowledge ','');
  const p=map.get(key);
  if(!p){continue}
  const diffs=[];
  for(const k of Object.keys(p)){
    if(k==='sel'||k==='box')continue;
    if(d[k]!==p[k]) diffs.push(k+': dev='+d[k]+' | proto='+p[k]);
  }
  if(p.box&&d.box){
    for(const k of ['w','h','x','y']){
      if(Math.abs((p.box[k]||0)-(d.box[k]||0))>0.6) diffs.push('box.'+k+': dev='+d.box[k]+' | proto='+p.box[k]);
    }
  }
  if(diffs.length) console.log('\n['+key+']\n  '+diffs.join('\n  '));
}
"", "description": "对比开发页与原型计算样式"}

