  display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:4px 8px 7px;
  font-size:9.5px;color:var(--ink-3);
}
.cm-count{font-family:var(--font-mono);font-size:8.5px}
.cm-count b{font-weight:500;color:var(--ink-2)}
.cm-sep{height:1px;background:var(--line-2);margin:6px 4px}
.cm-label{display:flex;align-items:center;gap:8px;padding:6px 8px 3px;font-size:9.5px;color:var(--ink-3)}
.cm-note{margin-left:auto;font-size:8.5px;color:var(--ink-3);font-weight:400}
.cm-label-sub{padding:4px 8px 2px;font-size:8.5px;color:var(--ink-3)}
.cm-item,.cm-check,.cm-radio{
  display:flex;align-items:center;gap:8px;width:100%;
  min-height:32px;padding:0 8px;
  border-radius:5px;
  text-align:left;
  font-size:11.5px;color:var(--ink-2);
  transition:background .12s,color .12s;
}
.cm-item:hover,.cm-check:hover,.cm-radio:hover{background:var(--surface-2);color:var(--ink)}
.cm-item.is-active,.cm-check.is-active,.cm-radio.is-active{background:var(--surface-2)}
.cm-icon{display:grid;place-items:center;width:16px;height:16px;flex:none;color:var(--ink-3)}
.cm-icon .ic{width:14px;height:14px}
.cm-main{flex:1;min-width:0}
.cm-hint{font-size:9.5px;color:var(--ink-3);white-space:nowrap}
.cm-check-box{
  display:grid;place-items:center;flex:none;
  width:14px;height:14px;
  border:1px solid var(--line);border-radius:3px;
  background:var(--surface);
  color:transparent;
}
.cm-check-box .ic{width:9px;height:9px;stroke-width:2.6}
.cm-check.is-active .cm-check-box{background:var(--prussian);border-color:var(--prussian);color:#fff}
.cm-radio-dot{
  width:13px;height:13px;flex:none;
  border:1px solid var(--line);border-radius:50%;
  background:var(--surface);
}
.cm-radio.is-active .cm-radio-dot{border:4px solid var(--prussian)}
.cm-radio.is-disabled{opacity:.45;cursor:not-allowed}
.cm-radio.is-disabled:hover{background:transparent;color:var(--ink-2)}
.cm-manage{padding-top:2px;color:var(--ink-3)}
.cm-ext{width:12px;height:12px;flex:none;color:var(--ink-3)}

/* model + reasoning popover */
.model-wrap{position:relative;flex:none}

  .settings-grid{grid-template-columns:130px minmax(0,1fr);gap:26px}
}
@media (max-width:900px){
  .page-topbar{
    display:flex;align-items:center;gap:10px;flex:none;
    height:52px;padding:0 14px;
    border-bottom:1px solid var(--line);background:var(--paper);
  }
  .page-topbar .mobile-sidebar-btn{display:grid;margin-right:0}
  .page-topbar-title{font-size:13px;font-weight:600}
  .page{padding:24px 20px 52px}
  .knowledge-grid{grid-template-columns:1fr}
  .debug-panel{position:static}
  .settings-grid{grid-template-columns:1fr;gap:18px;margin-top:18px}
  .settings-nav{position:static;flex-direction:row;flex-wrap:wrap;gap:4px}
  .settings-nav-item{height:28px;border:1px solid var(--line);background:var(--surface)}
  .settings-nav-item.is-active{background:var(--paper-2)}
  .agent-summary{grid-template-columns:28px minmax(0,1fr) 74px 16px;gap:12px}
  .agent-endpoint,.agent-skill-count{display:none}
  .agent-detail{padding-left:4px}
  .task-head{display:none}
  .task-summary{grid-template-columns:minmax(0,1fr) 82px 16px;gap:10px}
  .task-agent,.task-duration,.task-conv{display:none}
  .task-detail{grid-template-columns:1fr}
  .register-grid{grid-template-columns:1fr}
  .toolbar{flex-wrap:wrap}
  .tool-search{flex:1;min-width:200px}
}
@media (max-width:760px){
  .page{padding:20px 14px 44px}
  .page-head{flex-direction:column;align-items:flex-start;gap:14px}
  .page-title{font-size:22px}
  .page-actions{width:100%}
  .page-actions .btn{flex:1}
  .stats{gap:0 16px}
  .cap-block{padding:12px}
  .cap-hint{margin-left:0;flex-basis:100%}
  .cap-item{flex-wrap:wrap}
  .cap-item-actions{width:100%;justify-content:flex-end}
  .cap-toolbar .tool-search{max-width:none;flex-basis:100%}
  .stat{padding-right:16px;margin-right:16px}
  .stat-value{font-size:18px}
  .agent-detail,.task-detail{grid-template-columns:1fr}
  .detail-block.wide{grid-column:auto}
  .field-row,.settings-kv > div{grid-template-columns:1fr;gap:4px}
  .settings-actions{flex-wrap:wrap}
  .debug-row{flex-wrap:wrap}
  .seg{max-width:100%;overflow-x:auto}
  .doc-toolbar{flex-wrap:wrap}
  .doc-toolbar .select{width:100%}
  .inline-control{flex-wrap:wrap}
  .inline-control .input{max-width:none}
}


